### Étape 2 — Ajouter la requête de tronçons dans `TripSegmentRepository`

Dans `src/Repository/TripSegmentRepository.php`, ajoutez une méthode dédiée (elle servira aussi directement en **T-202** pour poser le verrou `PESSIMISTIC_WRITE`) :

```php
<?php

namespace App\Repository;

use App\Entity\Trip;
use App\Entity\TripSegment;
use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;
use Doctrine\DBAL\LockMode;
use Doctrine\Persistence\ManagerRegistry;

class TripSegmentRepository extends ServiceEntityRepository
{
    public function __construct(ManagerRegistry $registry)
    {
        parent::__construct($registry, TripSegment::class);
    }

    /**
     * Retourne les segments ordonnés pour le sous-trajet [startOrder, endOrder).
     *
     * @return TripSegment[]
     */
    public function findBetweenStopOrders(
        Trip $trip,
        int $startOrder,
        int $endOrder,
        bool $lockForUpdate = false,
    ): array {
        $qb = $this->createQueryBuilder('s')
            ->where('s.trip = :trip')
            ->andWhere('s.segmentOrder >= :startOrder')
            ->andWhere('s.segmentOrder < :endOrder')
            ->setParameter('trip', $trip)
            ->setParameter('startOrder', $startOrder)
            ->setParameter('endOrder', $endOrder)
            ->orderBy('s.segmentOrder', 'ASC');

        $query = $qb->getQuery();

        if ($lockForUpdate) {
            // Préparé pour T-202 (à exécuter obligatoirement dans une transaction)
            $query->setLockMode(LockMode::PESSIMISTIC_WRITE);
        }

        return $query->getResult();
    }
}
```

---

### Étape 3 — Créer `src/Service/RideBookingManager.php`

Voici le service central qui gère la validation du sous-tronçon, la disponibilité, le prix et la création de la réservation + `BookingSegment`.

```php
<?php

declare(strict_types=1);

namespace App\Service;

use App\Entity\Booking;
use App\Entity\BookingSegment;
use App\Entity\Trip;
use App\Entity\TripSegment;
use App\Entity\TripStop;
use App\Entity\User;
use App\Enum\BookingStatus;
use App\Enum\TripStatus;
use App\Exception\InvalidTripSegmentException;
use App\Exception\SeatsNotAvailableException;
use App\Exception\SelfBookingNotAllowedException;
use App\Repository\TripSegmentRepository;
use Doctrine\ORM\EntityManagerInterface;

final class RideBookingManager
{
    public function __construct(
        private readonly EntityManagerInterface $entityManager,
        private readonly TripSegmentRepository $segmentRepository,
    ) {
    }

    /**
     * Valide la cohérence des arrêts et retourne les segments traversés.
     *
     * @return TripSegment[]
     */
    public function resolveSegments(
        Trip $trip,
        TripStop $boardingStop,
        TripStop $alightingStop,
        bool $lockForUpdate = false,
    ): array {
        if ($boardingStop->getTrip()?->getId() !== $trip->getId()
            || $alightingStop->getTrip()?->getId() !== $trip->getId()
        ) {
            throw new InvalidTripSegmentException('Les arrêts sélectionnés n\'appartiennent pas à ce trajet.');
        }

        $startOrder = $boardingStop->getStopOrder();
        $endOrder = $alightingStop->getStopOrder();

        if ($startOrder >= $endOrder) {
            throw new InvalidTripSegmentException('L\'arrêt de descente doit être postérieur à l\'arrêt de montée.');
        }

        $segments = $this->segmentRepository->findBetweenStopOrders(
            $trip,
            $startOrder,
            $endOrder,
            $lockForUpdate
        );

        $expectedCount = $endOrder - $startOrder;
        if (count($segments) !== $expectedCount) {
            throw new InvalidTripSegmentException('Tronçon incomplet ou corrompu pour ce trajet.');
        }

        return $segments;
    }

    /**
     * Retourne le nombre maximum de places réservables sur une portion [i, j).
     */
    public function getAvailableSeats(Trip $trip, TripStop $boardingStop, TripStop $alightingStop): int
    {
        if ($trip->getStatus() !== TripStatus::SCHEDULED) {
            return 0;
        }

        $segments = $this->resolveSegments($trip, $boardingStop, $alightingStop);

        return min(array_map(
            static fn (TripSegment $segment): int => $segment->getAvailableSeats(),
            $segments
        ));
    }

    /**
     * Calcule le prix total pour un sous-tronçon et un nombre de places donné.
     */
    public function calculateSubTripPrice(
        Trip $trip,
        TripStop $boardingStop,
        TripStop $alightingStop,
        int $seats = 1,
    ): int {
        if ($seats < 1) {
            throw new InvalidTripSegmentException('Le nombre de places doit être au moins égal à 1.');
        }

        $segments = $this->resolveSegments($trip, $boardingStop, $alightingStop);
        $unitPrice = array_sum(array_map(
            static fn (TripSegment $segment): int => $segment->getPrice(),
            $segments
        ));

        return $unitPrice * $seats;
    }

    /**
     * Crée une réservation confirmée et décrémente les segments concernés.
     * (En T-202, on encadrera ce flux avec wrapInTransaction + lockForUpdate: true).
     */
    public function book(
        User $passenger,
        Trip $trip,
        TripStop $boardingStop,
        TripStop $alightingStop,
        int $seats = 1,
    ): Booking {
        if ($seats < 1) {
            throw new InvalidTripSegmentException('Vous devez réserver au moins 1 place.');
        }

        if ($trip->getDriver()?->getId() === $passenger->getId()) {
            throw new SelfBookingNotAllowedException('Un conducteur ne peut pas réserver sur son propre trajet.');
        }

        if ($trip->getStatus() !== TripStatus::SCHEDULED) {
            throw new InvalidTripSegmentException('Ce trajet n\'est plus ouvert à la réservation.');
        }

        if ($boardingStop->getEstimatedArrivalAt() <= new \DateTimeImmutable()) {
            throw new InvalidTripSegmentException('L\'horaire de montée pour ce tronçon est déjà dépassé.');
        }

        $segments = $this->resolveSegments($trip, $boardingStop, $alightingStop);

        // Vérification stricte de capacité sur CHAQUE segment intermédiaire
        foreach ($segments as $segment) {
            if ($segment->getAvailableSeats() < $seats) {
                throw new SeatsNotAvailableException(sprintf(
                    'Places insuffisantes sur le tronçon %s → %s (%d restante(s)).',
                    $segment->getFromStop()?->getCity()?->getName() ?? '?',
                    $segment->getToStop()?->getCity()?->getName() ?? '?',
                    $segment->getAvailableSeats()
                ));
            }
        }

        $unitPrice = 0;
        foreach ($segments as $segment) {
            $segment->setAvailableSeats($segment->getAvailableSeats() - $seats);
            $unitPrice += $segment->getPrice();
        }

        $booking = (new Booking())
            ->setPassenger($passenger)
            ->setTrip($trip)
            ->setBoardingStop($boardingStop)
            ->setAlightingStop($alightingStop)
            ->setSeatsBooked($seats)
            ->setTotalPrice($unitPrice * $seats)
            ->setStatus(BookingStatus::CONFIRMED)
            ->setCreatedAt(new \DateTimeImmutable());

        $this->entityManager->persist($booking);

        foreach ($segments as $segment) {
            $bookingSegment = (new BookingSegment())
                ->setBooking($booking)
                ->setSegment($segment)
                ->setSeatsCount($seats);

            $this->entityManager->persist($bookingSegment);
        }

        $this->entityManager->flush();

        return $booking;
    }
}
```

