### Étape 3 — Créer `src/Service/CancellationService.php`

```php
<?php

declare(strict_types=1);

namespace App\Service;

use App\Entity\Booking;
use App\Entity\Trip;
use App\Enum\BookingStatus;
use App\Enum\TripStatus;
use App\Exception\CancellationNotAllowedException;
use App\Repository\BookingRepository;
use App\Repository\TripSegmentRepository;
use Doctrine\DBAL\LockMode;
use Doctrine\ORM\EntityManagerInterface;
use Psr\Log\LoggerInterface;

final class CancellationService
{
    public function __construct(
        private readonly EntityManagerInterface $entityManager,
        private readonly BookingRepository $bookingRepository,
        private readonly TripSegmentRepository $segmentRepository,
        private readonly LoggerInterface $logger,
    ) {
    }

    /**
     * Calcule le remboursement passager avant confirmation (utile pour la modal E04).
     * >= 24h avant la montée : 100 % ; < 24h : 50 %.
     */
    public function previewPassengerRefund(Booking $booking, ?\DateTimeImmutable $now = null): int
    {
        $now ??= new \DateTimeImmutable();
        $boardingAt = $booking->getBoardingStop()?->getEstimatedArrivalAt();

        if ($boardingAt === null) {
            return 0;
        }

        $secondsBeforeDeparture = $boardingAt->getTimestamp() - $now->getTimestamp();
        if ($secondsBeforeDeparture >= 24 * 3600) {
            return $booking->getTotalPrice();
        }

        return (int) round($booking->getTotalPrice() * 0.5, 0, PHP_ROUND_HALF_UP);
    }

    /**
     * Annulation à l'initiative du passager :
     * libère les places sur les segments concernés et applique la politique 24h.
     */
    public function cancelByPassenger(Booking $booking, ?\DateTimeImmutable $now = null): Booking
    {
        $now ??= new \DateTimeImmutable();

        return $this->entityManager->wrapInTransaction(function () use ($booking, $now): Booking {
            // Verrouiller la réservation et le trajet
            $this->entityManager->lock($booking, LockMode::PESSIMISTIC_WRITE);
            $this->entityManager->refresh($booking);

            $trip = $booking->getTrip();
            if ($trip === null) {
                throw new CancellationNotAllowedException('Trajet introuvable pour cette réservation.');
            }

            $this->entityManager->lock($trip, LockMode::PESSIMISTIC_WRITE);
            $this->entityManager->refresh($trip);

            if ($booking->getStatus() !== BookingStatus::CONFIRMED) {
                throw new CancellationNotAllowedException('Cette réservation a déjà été annulée.');
            }

            if ($trip->getStatus() !== TripStatus::SCHEDULED) {
                throw new CancellationNotAllowedException('Impossible d\'annuler sur un trajet terminé ou annulé.');
            }

            $boardingStop = $booking->getBoardingStop();
            $alightingStop = $booking->getAlightingStop();
            if ($boardingStop === null || $alightingStop === null) {
                throw new CancellationNotAllowedException('Arrêts de réservation invalides.');
            }

            if ($now >= $boardingStop->getEstimatedArrivalAt()) {
                throw new CancellationNotAllowedException('Impossible d\'annuler après l\'heure de départ prévue.');
            }

            // Verrouiller les segments dans l'ordre croissant (anti-deadlock) et restaurer les places
            $segments = $this->segmentRepository->findBetweenStopOrders(
                $trip,
                $boardingStop->getStopOrder(),
                $alightingStop->getStopOrder(),
                lockForUpdate: true
            );

            foreach ($segments as $segment) {
                $segment->setAvailableSeats($segment->getAvailableSeats() + $booking->getSeatsBooked());
            }

            $refundAmount = $this->previewPassengerRefund($booking, $now);

            $booking
                ->setStatus(BookingStatus::CANCELLED_PASSENGER)
                ->setRefundAmount($refundAmount)
                ->setCancelledAt($now);

            return $booking;
        });
    }

    /**
     * Annulation à l'initiative du conducteur :
     * annule le trajet et toutes les réservations confirmées en cascade (remboursement 100 %).
     *
     * @return int Nombre de réservations annulées en cascade.
     */
    public function cancelByDriver(Trip $trip, ?\DateTimeImmutable $now = null): int
    {
        $now ??= new \DateTimeImmutable();

        return $this->entityManager->wrapInTransaction(function () use ($trip, $now): int {
            // Verrou exclusif sur le trajet : empêche toute nouvelle réservation concurrente
            $this->entityManager->lock($trip, LockMode::PESSIMISTIC_WRITE);
            $this->entityManager->refresh($trip);

            if ($trip->getStatus() !== TripStatus::SCHEDULED) {
                throw new CancellationNotAllowedException('Seul un trajet planifié peut être annulé.');
            }

            if ($now >= $trip->getDepartureAt()) {
                throw new CancellationNotAllowedException('Impossible d\'annuler un trajet déjà parti.');
            }

            $trip->setStatus(TripStatus::CANCELLED);

            $confirmedBookings = $this->bookingRepository->findConfirmedByTrip($trip);
            $cancelledCount = 0;

            foreach ($confirmedBookings as $booking) {
                $this->entityManager->lock($booking, LockMode::PESSIMISTIC_WRITE);
                $this->entityManager->refresh($booking);

                if ($booking->getStatus() !== BookingStatus::CONFIRMED) {
                    continue;
                }

                $boardingStop = $booking->getBoardingStop();
                $alightingStop = $booking->getAlightingStop();

                if ($boardingStop !== null && $alightingStop !== null) {
                    $segments = $this->segmentRepository->findBetweenStopOrders(
                        $trip,
                        $boardingStop->getStopOrder(),
                        $alightingStop->getStopOrder(),
                        lockForUpdate: true
                    );

                    foreach ($segments as $segment) {
                        $segment->setAvailableSeats($segment->getAvailableSeats() + $booking->getSeatsBooked());
                    }
                }

                $booking
                    ->setStatus(BookingStatus::CANCELLED_DRIVER)
                    ->setRefundAmount($booking->getTotalPrice())
                    ->setCancelledAt($now);

                $cancelledCount++;

                // Trace système / notification simulée pour audit
                $this->logger->info('Booking cancelled due to driver trip cancellation', [
                    'trip_id' => $trip->getId(),
                    'booking_id' => $booking->getId(),
                    'passenger_email' => $booking->getPassenger()?->getEmail(),
                    'refund_amount' => $booking->getTotalPrice(),
                ]);
            }

            return $cancelledCount;
        });
    }
}
```

