### Étape 4 — Test 2 : `tests/Integration/ConcurrentBookingTest.php` *(Vraie concurrence parallèle)*

On crée un petit script worker `tests/Support/attempt_booking.php` qui démarre le noyau `test` et tente `RideBookingManager::book(...)`, puis PHPUnit lance **2 processus simultanés** pour la dernière place restante.

#### 1. `tests/Support/attempt_booking.php`
```php
<?php

declare(strict_types=1);

use App\Entity\Trip;
use App\Entity\TripStop;
use App\Entity\User;
use App\Exception\SeatsNotAvailableException;
use App\Kernel;
use App\Service\RideBookingManager;
use Doctrine\ORM\EntityManagerInterface;

require dirname(__DIR__, 2) . '/vendor/autoload.php';

[$_, $passengerId, $tripId, $boardingStopId, $alightingStopId] = $argv;

$kernel = new Kernel('test', false);
$kernel->boot();

$container = $kernel->getContainer();
/** @var EntityManagerInterface $em */
$em = $container->get(EntityManagerInterface::class);
/** @var RideBookingManager $bookingManager */
$bookingManager = $container->get(RideBookingManager::class);

$passenger = $em->find(User::class, (int) $passengerId);
$trip = $em->find(Trip::class, (int) $tripId);
$from = $em->find(TripStop::class, (int) $boardingStopId);
$to = $em->find(TripStop::class, (int) $alightingStopId);

try {
    $bookingManager->book($passenger, $trip, $from, $to, 1);
    echo "BOOKED\n";
    exit(0);
} catch (SeatsNotAvailableException $e) {
    echo "REJECTED\n";
    exit(2);
}
```

#### 2. `tests/Integration/ConcurrentBookingTest.php`
```php
<?php

declare(strict_types=1);

namespace App\Tests\Integration;

use App\Entity\Booking;
use App\Enum\BookingStatus;
use App\Tests\Support\CarpoolingTestHelperTrait;
use Doctrine\ORM\EntityManagerInterface;
use Symfony\Bundle\FrameworkBundle\Test\KernelTestCase;
use Symfony\Component\Process\Process;

final class ConcurrentBookingTest extends KernelTestCase
{
    use CarpoolingTestHelperTrait;

    private EntityManagerInterface $em;

    protected function setUp(): void
    {
        self::bootKernel();
        $this->em = self::getContainer()->get(EntityManagerInterface::class);
        $this->resetDatabase($this->em);
    }

    public function testTwoSimultaneousBookingsForLastSeatAllowOnlyOneWinner(): void
    {
        $driver = $this->createUser($this->em, 'driver@test.ma', 'Karim');
        $p1 = $this->createUser($this->em, 'p1@test.ma', 'Amina');
        $p2 = $this->createUser($this->em, 'p2@test.ma', 'Youssef');
        $vehicle = $this->createVehicle($this->em, $driver);
        $agadir = $this->createCity($this->em, 'Agadir');
        $marrakech = $this->createCity($this->em, 'Marrakech');

        // 1 seule place disponible en base (commitée)
        ['trip' => $trip, 'stops' => $stops, 'segments' => $segments] = $this->createMultiStopTrip(
            $this->em,
            $driver,
            $vehicle,
            [$agadir, $marrakech],
            new \DateTimeImmutable('+3 days'),
            seats: 1,
            segmentPrices: [120]
        );

        $worker = dirname(__DIR__) . '/Support/attempt_booking.php';

        $proc1 = new Process([
            'php', $worker,
            (string) $p1->getId(),
            (string) $trip->getId(),
            (string) $stops[0]->getId(),
            (string) $stops[1]->getId(),
        ]);
        $proc2 = new Process([
            'php', $worker,
            (string) $p2->getId(),
            (string) $trip->getId(),
            (string) $stops[0]->getId(),
            (string) $stops[1]->getId(),
        ]);

        // Lancement simultané des 2 processus
        $proc1->start();
        $proc2->start();
        $proc1->wait();
        $proc2->wait();

        $results = [trim($proc1->getOutput()), trim($proc2->getOutput())];
        sort($results);

        // Exactement 1 BOOKED et 1 REJECTED (jamais 2 BOOKED)
        self::assertSame(['BOOKED', 'REJECTED'], $results);

        $this->em->clear();
        $confirmedCount = $this->em->getRepository(Booking::class)->count([
            'trip' => $trip->getId(),
            'status' => BookingStatus::CONFIRMED,
        ]);
        self::assertSame(1, $confirmedCount);

        $freshSegment = $this->em->find(get_class($segments[0]), $segments[0]->getId());
        self::assertSame(0, $freshSegment->getAvailableSeats());
    }
}
```

