        $this->cancellationService->cancelByPassenger($booking, $departureAt->modify('-12 hours'));

        self::assertSame(BookingStatus::CANCELLED_PASSENGER, $booking->getStatus());
        self::assertSame(60, $booking->getRefundAmount());
