use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\Routing\Attribute\Route;
use Symfony\Component\Security\Http\Attribute\IsGranted;

#[IsGranted('ROLE_USER')]
final class GeoController extends AbstractController
{
    #[Route('/api/geocode', name: 'api_geocode', methods: ['GET'])]
    public function geocode(Request $request, NominatimGeocodingService $geocoder): JsonResponse
    {
        $query = trim((string) $request->query->get('q', ''));
        if (mb_strlen($query) < 2) {
            return $this->json(['error' => 'Requête trop courte'], 400);
        }

        $point = $geocoder->geocode($query);
        if ($point === null) {
            return $this->json(['found' => false], 404);
        }

        return $this->json([
            'found' => true,
            'latitude' => $point->latitude,
            'longitude' => $point->longitude,
            'displayName' => $point->displayName,
        ]);
    }
