### Étape 2 — Contrôleur Stimulus `assets/controllers/trip_map_controller.js`

Un seul contrôleur Stimulus propre gère **les deux écrans** :
* Sur **E02**, il lit les `data-trip-map-*-value` rendues par Twig et trace immédiatement la route.
* Sur **E05**, il écoute les changements du formulaire (`updateRoute()`), appelle `/api/route-preview?cityIds=...`, trace la route OSRM sur la carte, met à jour les 3 KPIs (`Distance`, `Durée`, `Prix suggéré`) et branche le bouton **« Appliquer le prix suggéré »**.

```javascript
import { Controller } from '@hotwired/stimulus';

export default class extends Controller {
    static targets = [
        'canvas',
        'distance',
        'duration',
        'suggestedPrice',
        'suggestedPriceWrapper',
        'priceInput',
        'stopSelect'
    ];

    static values = {
        geometry: String,
        stops: Array,
        previewUrl: String
    };

    connect() {
        if (!window.L || !this.hasCanvasTarget) {
            return;
        }

        this.map = L.map(this.canvasTarget, { scrollWheelZoom: false }).setView([31.63, -8.0], 6);

        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 18,
            attribution: '&copy; OpenStreetMap · OSRM'
        }).addTo(this.map);

        this.routeLayer = L.layerGroup().addTo(this.map);

        // Mode E02 (données déjà présentes dans le HTML)
        if (this.hasGeometryValue && this.geometryValue) {
            try {
                const geometry = JSON.parse(this.geometryValue);
                this.renderMap(geometry, this.stopsValue || []);
            } catch (e) {
                console.error('Invalid route geometry JSON', e);
            }
        } else if (this.hasPreviewUrlValue) {
            // Mode E05 (calcul initial si des villes sont déjà présélectionnées)
            this.refreshPreview();
        }
    }

    disconnect() {
        if (this.map) {
            this.map.remove();
        }
    }

    async refreshPreview() {
        if (!this.hasPreviewUrlValue) {
            return;
        }

        const cityIds = this.stopSelectTargets
            .map((el) => el.value)
            .filter((val) => val !== '');

        // Il faut au moins départ + arrivée différents
        if (cityIds.length < 2 || new Set(cityIds).size < 2) {
            return;
        }

        try {
            const response = await fetch(`${this.previewUrlValue}?cityIds=${cityIds.join(',')}`);
            if (!response.ok) {
                return;
            }
            const data = await response.json();

            this.renderMap(data.geometry, data.stops);

            if (this.hasDistanceTarget) {
                this.distanceTarget.textContent = `${data.distanceKm} km`;
            }
            if (this.hasDurationTarget) {
                const h = Math.floor(data.durationMinutes / 60);
                const m = data.durationMinutes % 60;
                this.durationTarget.textContent = h > 0 ? `${h}h ${String(m).padStart(2, '0')}min` : `${m} min`;
            }
            if (this.hasSuggestedPriceTarget) {
                this.suggestedPriceTarget.textContent = `${data.suggestedPrice} DH`;
                this.currentSuggestedPrice = data.suggestedPrice;
                if (this.hasSuggestedPriceWrapperTarget) {
                    this.suggestedPriceWrapperTarget.classList.remove('hidden');
                }
            }
        } catch (err) {
            console.error('Route preview error', err);
        }
    }

    applySuggestedPrice() {
        if (this.hasPriceInputTarget && this.currentSuggestedPrice) {
            this.priceInputTarget.value = this.currentSuggestedPrice;
            this.priceInputTarget.dispatchEvent(new Event('input'));
        }
    }

    renderMap(geometry, stops) {
        if (!this.routeLayer) {
            return;
        }
        this.routeLayer.clearLayers();

        let boundsGroup = L.featureGroup();

        if (geometry && geometry.coordinates && geometry.coordinates.length > 0) {
            const line = L.geoJSON(geometry, {
                style: {
                    color: '#059669',
                    weight: 4,
                    opacity: 0.9
                }
            });
            line.addTo(this.routeLayer);
            boundsGroup.addLayer(line);
        }

        stops.forEach((stop, index) => {
            const icon = L.divIcon({
                className: 'safar-map-pin',
                html: `<div style="width:26px;height:26px;border-radius:9999px;background:#059669;color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,0.3);">${index + 1}</div>`,
                iconSize: [26, 26],
                iconAnchor: [13, 13]
            });

            const marker = L.marker([stop.lat, stop.lng], { icon })
                .bindPopup(`<strong>${index + 1}. ${stop.name}</strong>`);
            marker.addTo(this.routeLayer);
            boundsGroup.addLayer(marker);
        });

        if (boundsGroup.getLayers().length > 0) {
            this.map.fitBounds(boundsGroup.getBounds(), { padding: [30, 30] });
        }
    }
}
```

