## 4. Tests Unitaires rapides (Pricing + OSRM Fallback)

Créez **`tests/Unit/PricingAndOsrmTest.php`** :
```php
<?php

declare(strict_types=1);

namespace App\Tests\Unit;

use App\Entity\City;
use App\Service\OsrmRoutingService;
use App\Service\PricingCalculatorService;
use PHPUnit\Framework\TestCase;
use Psr\Log\NullLogger;
use Symfony\Component\Cache\Adapter\ArrayAdapter;
use Symfony\Component\HttpClient\MockHttpClient;
use Symfony\Component\HttpClient\Response\MockResponse;

final class PricingAndOsrmTest extends TestCase
{
    public function testPricingSplitsAcrossLegsWithoutRoundingDrift(): void
    {
        $pricing = new PricingCalculatorService();

        $total = $pricing->suggestTotalPrice(250.0);
        self::assertGreaterThan(80, $total);

        $split = $pricing->splitPriceAcrossLegs($total, [100.0, 150.0]);
        self::assertCount(2, $split);
        self::assertSame($total, array_sum($split));
    }

    public function testOsrmFallsBackToHaversineWhenApiFails(): void
    {
        $mockClient = new MockHttpClient([
            new MockResponse('', ['http_code' => 503]),
        ]);

        $osrm = new OsrmRoutingService(
            $mockClient,
            new ArrayAdapter(),
            new NullLogger(),
            'https://router.project-osrm.org',
            'SafarCar-Test/1.0'
        );

        $agadir = (new City())->setName('Agadir')->setLatitude(30.4278)->setLongitude(-9.5981);
        $marrakech = (new City())->setName('Marrakech')->setLatitude(31.6295)->setLongitude(-7.9811);

        $result = $osrm->calculateRoute([$agadir, $marrakech]);

        self::assertTrue($result->isFallback);
        self::assertGreaterThan(200.0, $result->totalDistanceKm);
        self::assertSame('LineString', $result->geoJsonGeometry['type']);
    }
}
```

